```
const LOC_DIVISION = /geography and map division/i;
const LOC_FREE_USE = /free to use and reuse/i;
const LOC_PUBLIC_DOMAIN = /\b(?:is|are|in the|in) (?:the )?public domain\b|publicdomain\/(?:mark|zero)\/1\.0|noc-us/i;
const LOC_RESTRICTED = /all rights reserved|permission (?:is )?required|rights status not evaluated|copyright undetermined|may be restricted|under copyright|protected by copyright|non[ -]?commercial|contact (?:the )?host/i;
export function locRights(value, advisory) {
  const rights = text(value);
